(async () => {
  const s = window.__toolboxStore;
  if (!s) return JSON.stringify({ error: '拿不到存储层' });
  const out = {};

  // 造一张小图（64×64 PNG），当作自定义元件的配图
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = '#3b6bff'; g.fillRect(0, 0, 64, 64);
  g.fillStyle = '#fff'; g.font = 'bold 28px sans-serif'; g.fillText('X', 20, 44);
  const blob = await new Promise((r) => c.toBlob(r, 'image/png'));
  out.imageBytes = blob.size;

  // ① 自建一个带图的自定义元件
  const libId = await s.saveLibraryComponent({
    id: 'xyz-module', name: 'XYZ 模块', category: '模块',
    purpose: '测试元件随作品传播', appearance: '蓝色小板，四个针脚',
    polarity: '有方向：圆点那角是 1 脚', howToRead: '看板上丝印',
    source: 'user_created', author: '小明', image: blob,
    pinCount: 4, package: 'DIP-4', commonModels: ['XYZ-1'],
    commonMistakes: ['插反了不工作'], tags: ['测试'], usedInProjects: ['传播测试'],
  });
  out.libId = libId;

  // ② 建一个项目，两行 BOM：一行用内置电阻，一行用刚建的自定义元件
  const pid = await s.createProject({ name: '传播测试项目' });
  await s.addComponent(pid, { name: '电阻', type: '基础元件', model: '220Ω', libraryId: 'resistor', quantity: 2 });
  await s.addComponent(pid, { name: 'XYZ 模块', type: '模块', model: 'XYZ-1', libraryId: libId, quantity: 1 });
  const bundle = await s.getProject(pid);
  out.projectId = pid;
  out.rows = bundle.components.map((x) => ({ name: x.name, libraryId: x.libraryId || null }));
  out.libraryTotal = (await s.listLibrary()).length;
  return JSON.stringify(out);
})()
